+QString FolderModel::stackForItem(const KFileItem &item) const
+{
+    if (item.isNull() || item.isDir() || item.isDesktopFile()) {
+        return QString();
+    }
+
+    const QMimeType mime = item.determineMimeType();
+    const QString name = mime.name();
+
+    if (name.startsWith(QLatin1String("image/"))) {
+        return QStringLiteral("images");
+    } else if (name.startsWith(QLatin1String("video/"))) {
+        return QStringLiteral("videos");
+    } else if (name.startsWith(QLatin1String("audio/"))) {
+        return QStringLiteral("audio");
+    } else if (mime.inherits(QStringLiteral("text/plain")) || name == QLatin1String("application/pdf") || name == QLatin1String("application/msword")
+               || name == QLatin1String("application/rtf") || name == QLatin1String("application/epub+zip")
+               || name.startsWith(QLatin1String("application/vnd.oasis.opendocument."))
+               || name.startsWith(QLatin1String("application/vnd.openxmlformats-officedocument.")) || name.startsWith(QLatin1String("application/vnd.ms-"))) {
+        return QStringLiteral("documents");
+    }
+
+    return QStringLiteral("other");
+}
