+QString FolderModel::stackForIndex(const QModelIndex &index) const
+{
+    if (!m_useStacks || !m_stack.isEmpty() || !index.isValid()) {
+        return QString();
+    }
+
+    const KFileItem item = itemForIndex(index);
+    const QString stack = stackForItem(item);
+
+    if (stack.isEmpty()) {
+        return QString();
+    }
+
+    if (m_stacksDirty) {
+        updateStacks();
+    }
+
+    return m_stackHeads.value(stack) == item.url() ? stack : QString();
+}
+
+void FolderModel::updateStacks() const
+{
+    m_stacksDirty = false;
+    m_stackMembers.clear();
+    const QHash<QString, QUrl> oldHeads = std::exchange(m_stackHeads, {});
+
+    if (!m_useStacks || !m_stack.isEmpty()) {
+        return;
+    }
+
+    for (int i = 0; i < m_dirModel->rowCount(); ++i) {
+        const KFileItem item = m_dirModel->itemForIndex(m_dirModel->index(i, 0));
+        const QString stack = stackForItem(item);
+
+        if (!stack.isEmpty() && filterAcceptsItem(item)) {
+            m_stackMembers[stack].append(item.url());
+        }
+    }
+
+    // A stack needs at least two files. It takes the place of one of them, which is kept
+    // while it's there so the stack doesn't move; otherwise the first one by name.
+    for (auto it = m_stackMembers.cbegin(); it != m_stackMembers.cend(); ++it) {
+        if (it.value().size() < 2) {
+            continue;
+        }
+        const QUrl oldHead = oldHeads.value(it.key());
+        if (it.value().contains(oldHead)) {
+            m_stackHeads.insert(it.key(), oldHead);
+        } else {
+            m_stackHeads.insert(it.key(), *std::min_element(it.value().cbegin(), it.value().cend(), [](const QUrl &a, const QUrl &b) {
+                                    return a.fileName() < b.fileName();
+                                }));
+        }
+    }
+}
